import{_ as e,a as d,o,a6 as a}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse('{"title":"Catalog Attribute — Detail (GraphQL)","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-catalog-attribute-detail","title":"Attribute Detail (with translations and options)","description":"Fetch a single attribute by IRI including all locale translations and — for select/multiselect/checkbox types — all options with their own translations.","query":"query AdminCatalogAttribute($id: ID!) {\\n  adminAttribute(id: $id) {\\n    id\\n    _id\\n    code\\n    type\\n    adminName\\n    isRequired\\n    isUnique\\n    valuePerLocale\\n    valuePerChannel\\n    isFilterable\\n    isConfigurable\\n    isVisibleOnFront\\n    isUserDefined\\n    swatchType\\n    position\\n    locale\\n    validation\\n    defaultValue\\n    isComparable\\n    enableWysiwyg\\n    regex\\n    createdAt\\n    updatedAt\\n    translations\\n    options\\n  }\\n}\\n","variables":"{\\n  \\"id\\": \\"/api/admin/catalog/attributes/12\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"adminAttribute\\": {\\n      \\"id\\": \\"/api/admin/catalog/attributes/12\\",\\n      \\"_id\\": 12,\\n      \\"code\\": \\"color\\",\\n      \\"type\\": \\"select\\",\\n      \\"adminName\\": \\"Color\\",\\n      \\"isRequired\\": 0,\\n      \\"isUnique\\": 0,\\n      \\"valuePerLocale\\": 0,\\n      \\"valuePerChannel\\": 0,\\n      \\"isFilterable\\": 1,\\n      \\"isConfigurable\\": 1,\\n      \\"isVisibleOnFront\\": 1,\\n      \\"isUserDefined\\": 1,\\n      \\"swatchType\\": \\"color\\",\\n      \\"position\\": 5,\\n      \\"locale\\": \\"en\\",\\n      \\"validation\\": null,\\n      \\"defaultValue\\": null,\\n      \\"isComparable\\": 0,\\n      \\"enableWysiwyg\\": 0,\\n      \\"regex\\": null,\\n      \\"createdAt\\": \\"2026-01-12T08:15:00+00:00\\",\\n      \\"updatedAt\\": \\"2026-04-30T14:20:09+00:00\\",\\n      \\"translations\\": [\\n        { \\"locale\\": \\"en\\", \\"name\\": \\"Color\\" },\\n        { \\"locale\\": \\"fr\\", \\"name\\": \\"Couleur\\" }\\n      ],\\n      \\"options\\": [\\n        {\\n          \\"id\\": 33,\\n          \\"adminName\\": \\"Red\\",\\n          \\"sortOrder\\": 1,\\n          \\"swatchValue\\": \\"#FF0000\\",\\n          \\"swatchValueUrl\\": null,\\n          \\"translations\\": [\\n            { \\"locale\\": \\"en\\", \\"label\\": \\"Red\\" },\\n            { \\"locale\\": \\"fr\\", \\"label\\": \\"Rouge\\" }\\n          ]\\n        },\\n        {\\n          \\"id\\": 34,\\n          \\"adminName\\": \\"Blue\\",\\n          \\"sortOrder\\": 2,\\n          \\"swatchValue\\": \\"#0000FF\\",\\n          \\"swatchValueUrl\\": null,\\n          \\"translations\\": [\\n            { \\"locale\\": \\"en\\", \\"label\\": \\"Blue\\" },\\n            { \\"locale\\": \\"fr\\", \\"label\\": \\"Bleu\\" }\\n          ]\\n        }\\n      ]\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/catalog/attributes/attributes-detail.md","filePath":"api/graphql-api/admin/catalog/attributes/attributes-detail.md","lastUpdated":1787290888000}'),r={name:"api/graphql-api/admin/catalog/attributes/attributes-detail.md"};function n(i,t,c,l,s,h){return o(),d("div",null,t[0]||(t[0]=[a('<h1 id="catalog-attribute-—-detail-graphql" tabindex="-1">Catalog Attribute — Detail (GraphQL) <a class="header-anchor" href="#catalog-attribute-—-detail-graphql" aria-label="Permalink to &quot;Catalog Attribute — Detail (GraphQL)&quot;">​</a></h1><p>GraphQL item query that returns a single attribute by its IRI, including the <strong>full translations array</strong> (every locale present in the database) and — for <code>select</code>, <code>multiselect</code>, and <code>checkbox</code> types — all <strong>options</strong> with their own locale translations.</p><p>This is the query to call when an admin needs complete metadata for an attribute — e.g. when pre-populating the edit form in Catalog → Attributes.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th></tr></thead><tbody><tr><td><code>adminAttribute</code></td><td>Query (item)</td></tr></tbody></table><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>ID!</code></td><td>Yes</td><td>API Platform IRI of the attribute (e.g. <code>&quot;/api/admin/catalog/attributes/12&quot;</code>)</td></tr></tbody></table><p>Take the IRI straight from the <code>id</code> of an <a href="/api/graphql-api/admin/catalog/attributes/attributes-listing.html"><code>adminAttributes</code></a> edge node, or build it as <code>/api/admin/catalog/attributes/&lt;numericId&gt;</code>.</p><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>ID</code></td><td>API Platform IRI (e.g. <code>/api/admin/catalog/attributes/12</code>)</td></tr><tr><td><code>_id</code></td><td><code>Int</code></td><td>Raw attribute ID</td></tr><tr><td><code>code</code></td><td><code>String</code></td><td>Attribute code (e.g. <code>color</code>, <code>size</code>)</td></tr><tr><td><code>type</code></td><td><code>String</code></td><td>Attribute type (e.g. <code>select</code>, <code>text</code>, <code>boolean</code>)</td></tr><tr><td><code>adminName</code></td><td><code>String</code></td><td>Internal admin-facing label</td></tr><tr><td><code>isRequired</code></td><td><code>Int</code></td><td><code>1</code> = required on product forms</td></tr><tr><td><code>isUnique</code></td><td><code>Int</code></td><td><code>1</code> = value must be unique across products</td></tr><tr><td><code>valuePerLocale</code></td><td><code>Int</code></td><td><code>1</code> = separate value per store locale</td></tr><tr><td><code>valuePerChannel</code></td><td><code>Int</code></td><td><code>1</code> = separate value per channel</td></tr><tr><td><code>isFilterable</code></td><td><code>Int</code></td><td><code>1</code> = appears in layered navigation</td></tr><tr><td><code>isConfigurable</code></td><td><code>Int</code></td><td><code>1</code> = used as a configurable variant axis</td></tr><tr><td><code>isVisibleOnFront</code></td><td><code>Int</code></td><td><code>1</code> = shown on the storefront product page</td></tr><tr><td><code>isUserDefined</code></td><td><code>Int</code></td><td><code>1</code> = admin-created (not a system attribute)</td></tr><tr><td><code>swatchType</code></td><td><code>String</code></td><td>Swatch mode (<code>color</code>, <code>image</code>, <code>text</code>); <code>null</code> for non-swatch types</td></tr><tr><td><code>position</code></td><td><code>Int</code></td><td>Display order position</td></tr><tr><td><code>locale</code></td><td><code>String</code></td><td>App locale used for top-level scalar fields</td></tr><tr><td><code>validation</code></td><td><code>String</code></td><td>Validation rule string (e.g. <code>numeric</code>, <code>email</code>); <code>null</code> if none</td></tr><tr><td><code>defaultValue</code></td><td><code>String</code></td><td>Default value; <code>null</code> if not configured</td></tr><tr><td><code>isComparable</code></td><td><code>Int</code></td><td><code>1</code> if shown in the storefront product-compare table, else <code>0</code></td></tr><tr><td><code>enableWysiwyg</code></td><td><code>Int</code></td><td><code>1</code> if a rich-text editor is used for a <code>textarea</code> attribute, else <code>0</code></td></tr><tr><td><code>regex</code></td><td><code>String</code></td><td>Custom regex pattern, used when <code>validation</code> is <code>regex</code>; <code>null</code> otherwise</td></tr><tr><td><code>createdAt</code></td><td><code>String</code></td><td>ISO 8601 creation timestamp</td></tr><tr><td><code>updatedAt</code></td><td><code>String</code></td><td>ISO 8601 last-update timestamp</td></tr><tr><td><code>translations</code></td><td>scalar (JSON array)</td><td>All locale translations — see shape below</td></tr><tr><td><code>options</code></td><td>Iterable</td><td>Options for <code>select</code>, <code>multiselect</code>, and <code>checkbox</code> types; <code>[]</code> for every other type</td></tr></tbody></table><h3 id="translations-item-shape" tabindex="-1"><code>translations</code> item shape <a class="header-anchor" href="#translations-item-shape" aria-label="Permalink to &quot;`translations` item shape&quot;">​</a></h3><p><code>translations</code> is returned as a <strong>plain JSON array</strong> (scalar in GraphQL). Each element corresponds to one locale row in <code>attribute_translations</code>:</p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>locale</code></td><td>string</td><td>Locale code (e.g. <code>en</code>, <code>fr</code>)</td></tr><tr><td><code>name</code></td><td>string|null</td><td>Locale-specific attribute display name</td></tr></tbody></table><h3 id="options-item-shape" tabindex="-1"><code>options[]</code> item shape <a class="header-anchor" href="#options-item-shape" aria-label="Permalink to &quot;`options[]` item shape&quot;">​</a></h3><p><code>options</code> is returned as a <strong>plain JSON array</strong> (scalar in GraphQL). Each element corresponds to one row in <code>attribute_options</code>:</p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Option ID</td></tr><tr><td><code>adminName</code></td><td>string</td><td>Internal admin label for the option</td></tr><tr><td><code>sortOrder</code></td><td>integer</td><td>Display sort order</td></tr><tr><td><code>swatchValue</code></td><td>string|null</td><td>Swatch value (hex for <code>color</code>, path for <code>image</code>, text for <code>text</code>); <code>null</code> otherwise</td></tr><tr><td><code>swatchValueUrl</code></td><td>string|null</td><td>Full URL to the swatch image for <code>image</code> swatches; <code>null</code> for other types</td></tr><tr><td><code>translations</code></td><td>array</td><td>Locale translations for this option (see below)</td></tr></tbody></table><h3 id="options-translations-item-shape" tabindex="-1"><code>options[].translations[]</code> item shape <a class="header-anchor" href="#options-translations-item-shape" aria-label="Permalink to &quot;`options[].translations[]` item shape&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>locale</code></td><td>string</td><td>Locale code (e.g. <code>en</code>, <code>fr</code>)</td></tr><tr><td><code>label</code></td><td>string|null</td><td>Locale-specific display label for the option</td></tr></tbody></table><h3 id="translations-and-options-are-json-scalars" tabindex="-1">Translations and Options Are JSON Scalars <a class="header-anchor" href="#translations-and-options-are-json-scalars" aria-label="Permalink to &quot;Translations and Options Are JSON Scalars&quot;">​</a></h3><p>Select <code>translations</code> and <code>options</code> as <strong>bare fields</strong> — a sub-selection is a schema error. Each returns its whole structure in one piece, including every option&#39;s own nested <code>translations</code>.</p><p>An option carries <code>id</code> (numeric, not an IRI), <code>adminName</code>, <code>sortOrder</code>, <code>swatchValue</code>, <code>swatchValueUrl</code>, and <code>translations</code>. Only <code>select</code>, <code>multiselect</code>, and <code>checkbox</code> attributes have options; every other type returns an empty list.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Condition</th><th>Result</th></tr></thead><tbody><tr><td>Unknown or deleted id</td><td>HTTP <code>200</code> with <code>Attribute not found.</code> in <code>errors[]</code> and <code>null</code> in <code>data.adminAttribute</code></td></tr><tr><td>Missing or invalid token</td><td>HTTP <code>401</code> with <code>{&quot;message&quot;: &quot;Unauthenticated.&quot;, &quot;error&quot;: &quot;unauthenticated&quot;}</code> — rejected by the transport before GraphQL runs</td></tr></tbody></table><h2 id="working-with-this-query" tabindex="-1">Working With This Query <a class="header-anchor" href="#working-with-this-query" aria-label="Permalink to &quot;Working With This Query&quot;">​</a></h2><ul><li><strong><code>options</code> is <code>[]</code> for a non-option type, not <code>null</code>.</strong> Only <code>select</code>, <code>multiselect</code>, and <code>checkbox</code> carry options; a <code>text</code> attribute returns an empty list. Test the length, not for null.</li><li><strong><code>translations</code> carries one entry per stored locale row</strong>, not just the requested one, so a multi-locale store returns them all.</li><li><strong>An option&#39;s <code>id</code> is the numeric option id</strong>, not an IRI — unlike the attribute&#39;s own <code>id</code>. Send that number when referencing the option on a product&#39;s attribute value.</li><li><strong>The boolean flags are integers</strong>, <code>0</code> or <code>1</code>, not booleans.</li><li><strong>The <code>id</code> argument is the IRI, not the number.</strong> Build it as <code>/api/admin/catalog/attributes/&lt;_id&gt;</code> or pass a listing edge&#39;s <code>id</code> straight through.</li></ul>',25)]))}const b=e(r,[["render",n]]);export{p as __pageData,b as default};
